"""Build complete, offline, searchable research appendices.

No narrative report is composed here. All source data are rendered as text,
with raw records, source readings and scholarly decisions kept distinct.
"""
import csv,html,json,re
from pathlib import Path
from collections import Counter,defaultdict
from analysis_data import HERE,load_records,load_analysis_tokens,load_annotations,load_ancestors,tsv,jsonlines
from quantify import LANGS,lect,input_for,outcome

DEST=HERE/'appendices'
NAMES={'Sh':'Shina','Phal':'Palula','Sv':'Sauji','Kalk':'Kalkoti','Kund':'Kundal Shahi','bro':'Brokskat','Ush':'Ushojo'}
STYLE='''
:root{color-scheme:light;--ink:#192b35;--muted:#58666b;--line:#dbe1df;--paper:#fcfcf8;--accent:#185c54}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
header,main,footer{max-width:1380px;margin:auto;padding:28px 36px}header{border-bottom:1px solid var(--line)}h1{font:38px/1.15 Georgia,serif;margin:8px 0 14px}h2{font:27px/1.25 Georgia,serif}h3{margin:20px 0 8px}p{max-width:1000px}a{color:var(--accent)}.eyebrow{letter-spacing:.12em;text-transform:uppercase;font-size:12px;font-weight:700}.muted,small{color:var(--muted)}
.toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:end;padding:18px 0;position:sticky;top:0;background:var(--paper);z-index:3}.toolbar label{font-size:12px;font-weight:650;display:flex;flex-direction:column;gap:5px}input,select,button{font:inherit;padding:9px 12px;border:1px solid #9badab;border-radius:5px;background:white;color:var(--ink)}input{width:min(480px,80vw)}button{cursor:pointer}button:disabled{opacity:.35;cursor:default}.count{margin:8px 0;color:var(--muted)}.scroll{overflow:auto;max-width:100%}table{border-collapse:collapse;width:100%;font-size:14px}th{text-align:left;background:#edf2ef;font-size:12px;letter-spacing:.02em}td,th{padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:top}td.form,.phon{font-family:"Charis SIL","Noto Serif","Gentium Plus",Georgia,serif;font-size:17px}tr.detail>td{padding:18px 24px;background:#f2f5f0}details>summary{cursor:pointer;color:var(--accent)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace;background:#e9eeea;padding:14px}code{font:12px ui-monospace,monospace}.pill{display:inline-block;font-size:11px;line-height:1.3;border:1px solid #acbcb5;border-radius:4px;padding:3px 6px;margin:2px}.notice{border-left:3px solid #b18443;padding:8px 16px;background:#f6f1e7}.analysis{max-width:1050px}.kv{display:grid;grid-template-columns:180px 1fr;gap:8px 16px;font-size:14px}.kv dt{font-weight:650}.kv dd{margin:0;overflow-wrap:anywhere}.pager{display:flex;gap:10px;align-items:center;padding:18px 0}.downloads{display:flex;gap:16px;flex-wrap:wrap;font-size:14px}.empty{color:var(--muted);font-style:italic}footer{font-size:13px;border-top:1px solid var(--line)}
@media(max-width:700px){header,main,footer{padding:20px 16px}h1{font-size:29px}.toolbar{position:static}.kv{grid-template-columns:1fr}.kv dd{margin-bottom:12px}td,th{padding:8px}}
.family-card{border:1px solid var(--line);border-radius:6px;padding:18px 22px;margin:14px 0;background:#fff}.family-card h2{font-size:23px;margin:0 0 8px}.family-card .card-meta{font-size:13px;color:var(--muted);margin:8px 0 14px}.family-card .analysis{max-width:100%;min-width:0}.family-card .analysis>p{max-width:1000px}.family-card .language-panel{table-layout:fixed}.family-card .language-panel td:first-child,.family-card .language-panel th:first-child{width:140px}.family-card .language-panel td{overflow-wrap:anywhere}.family-card .scroll{min-width:0}.family-card .analysis>.scroll:not(:first-child) table:not(.language-panel){min-width:1000px}
.quant-table{table-layout:fixed}.quant-table td,.quant-table th{overflow-wrap:anywhere}.quant-table details p{max-width:none}
@media print{.toolbar,.pager,button{display:none}header,main,footer{padding:12px}body{font-size:11px}.scroll{overflow:visible}pre{font-size:9px}a{color:inherit}tr{break-inside:avoid}}
'''

SCRIPT=r'''
const D=JSON.parse(document.getElementById('data').textContent), $=s=>document.querySelector(s);
const records=D.records, byFamily=new Map(), byId=new Map();
for(const r of records){byId.set(r.analysis_token_id,r);if(r.research_family_id){if(!byFamily.has(r.research_family_id))byFamily.set(r.research_family_id,[]);byFamily.get(r.research_family_id).push(r)}}
const plain=v=>typeof v==='object'?JSON.stringify(v):String(v??'');
const norm=v=>plain(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const human=v=>plain(v).replaceAll('-',' ');
const elem=(tag,text,cls)=>{let e=document.createElement(tag);if(text!==undefined)e.textContent=plain(text);if(cls)e.className=cls;return e};
function para(parent,text,cls){if(text)parent.append(elem('p',text,cls))}
function jsonDetails(parent,label,value){if(!value||Array.isArray(value)&&!value.length)return;let d=elem('details');d.append(elem('summary',label),elem('pre',JSON.stringify(value,null,2)));parent.append(d)}
function table(parent,heads,rows){let wrap=elem('div',undefined,'scroll'),t=elem('table'),h=elem('tr');if(heads.length===2)t.className='language-panel';heads.forEach(x=>h.append(elem('th',x)));let thead=elem('thead');thead.append(h);t.append(thead);let b=elem('tbody');for(let cells of rows){let tr=elem('tr');for(let x of cells)tr.append(x instanceof Node?x:elem('td',x));b.append(tr)}t.append(b);wrap.append(t);parent.append(wrap);return b}
function reading(r){return r.reading_form||r.research_original||r.original}
function rNotes(r){let d=elem('details');d.append(elem('summary','Evidence and raw fields'));let box=elem('div');para(box,r.branch_analysis);para(box,r.research_link_evidence);para(box,r.etymological_assessment);for(let a of r.additional_record_annotations||[])para(box,a.analysis||a.basis||a.note);jsonDetails(box,'Record decisions',r.record_decisions);jsonDetails(box,'Formation decisions',r.formation_decisions);jsonDetails(box,'Primary readings and observations',[...(r.primary_table_readings||[]),...(r.source_observations||[])]);jsonDetails(box,'Complete record / analysis token',r);d.append(box);return d}
function recordCells(r,notes=true){let form=elem('td',reading(r),'form'),id=elem('td');id.append(elem('code',r.analysis_token_id));let src=elem('td',r.source_keys);para(src,r.dialect_tags,'muted');let review=elem('td',r.individual_review);if(r.strict_exclusion)para(review,'Excluded from strict predictions: '+r.strict_exclusion);if(notes)review.append(rNotes(r));return[id,elem('td',D.names[r.language_id]),form,elem('td',r.research_gloss),elem('td',r.research_ancestor_id||r.research_family_id||'Unlinked'),src,elem('td',r.display_outcome),review]}
const rHeads=['Record / token','Language','Reading','Meaning','Research input','Source / lect','Outcome','Review and evidence'];
function familyDetails(f){let d=elem('details');d.append(elem('summary','Open complete dossier'));let body=elem('div',undefined,'analysis');para(body,f.analysis);if(f.unresolved)para(body,'Unresolved: '+f.unresolved,'notice');let dl=elem('dl',undefined,'kv');for(let [k,v] of [['Input assessment',f.input],['Formation',f.formation],['Review status',f.status],['Annotation history',f.annotation_history.join(' → ')],['Revision reason',f.revision_reason]]){if(v){dl.append(elem('dt',k),elem('dd',v))}}body.append(dl);table(body,['Language','Source readings and outcomes'],D.languages.map(l=>[D.names[l],f.language_panel[l].length?f.language_panel[l].map(x=>x.form+' ['+x.outcome+'; '+x.source+'; '+x.lect+']').join(' | '):'No research-linked record in the frozen corpus']));jsonDetails(body,'Ancestral formations in this family',f.ancestors);body.append(elem('h3','Every research-linked record'));table(body,rHeads,(byFamily.get(f.family_id)||[]).map(r=>recordCells(r)));let moved=records.filter(r=>r.family_id===f.family_id&&r.research_family_id!==f.family_id);if(moved.length){body.append(elem('h3','Raw database members reassigned by the research'));table(body,rHeads,moved.map(r=>recordCells(r)))}d.append(body);return d}
let page=0,filtered=[],size=30;
const searchIndex=new Map();for(let f of D.families)searchIndex.set('f'+f.family_id,norm([f.family_id,f.headword,f.gloss,f.analysis,f.unresolved,f.formation,f.language_panel]));for(let r of records)searchIndex.set('r'+r.analysis_token_id,norm([r.analysis_token_id,r.original,reading(r),r.research_gloss,r.research_family_id,r.research_ancestor_id,r.source_keys,r.dialect_tags,r.research_link_evidence,r.etymological_assessment,r.additional_record_annotations]));
function update(reset=true){if(reset)page=0;let mode=$('#mode').value,q=norm($('#search').value).trim(),lang=$('#language').value,review=$('#review').value;$('#review').disabled=mode==='families';
 filtered=(mode==='families'?D.families:records).filter(x=>{if(mode==='families'){if(lang&&!x.language_panel[lang].length)return false;if(/^\d+(?:[a-z])?$/.test(q))return x.family_id===q;return !q||searchIndex.get('f'+x.family_id).includes(q)}if(lang&&x.language_id!==lang)return false;if(review==='unlinked'&&x.research_family_id)return false;if(review==='excluded'&&!x.strict_exclusion)return false;if(review==='explicit'&&['unlinked-inventory','family-context-first-pass'].includes(x.individual_review))return false;if(q.startsWith('f_'))return x.id===q||x.analysis_token_id===q;return !q||searchIndex.get('r'+x.analysis_token_id).includes(q)});render()}
function render(){let mode=$('#mode').value,box=$('#results');box.replaceChildren();let unit=mode==='families'?(filtered.length===1?'family dossier':'family dossiers'):(filtered.length===1?'analysis token':'analysis tokens');$('#count').textContent=filtered.length.toLocaleString()+' '+unit+' · page '+(page+1)+' of '+Math.max(1,Math.ceil(filtered.length/size));let rr=filtered.slice(page*size,(page+1)*size);if(mode==='families'){for(let f of rr){let card=elem('article',undefined,'family-card');card.append(elem('h2',f.family_id+' · '+f.headword+' — '+f.gloss.replace(/<[^>]*>/g,'')));para(card,human(f.formation)+' · '+human(f.status),'card-meta');card.append(familyDetails(f));box.append(card)}}else table(box,rHeads,rr.map(r=>recordCells(r)));$('#prev').disabled=page===0;$('#next').disabled=(page+1)*size>=filtered.length}
$('#search').addEventListener('input',()=>update());for(let id of ['mode','language','review'])$('#'+id).addEventListener('change',()=>update());$('#prev').onclick=()=>{page--;update(false)};$('#next').onclick=()=>{page++;update(false)};
const hash=decodeURIComponent(location.hash.slice(1));if(hash){$('#search').value=hash.startsWith('family-')?hash.slice(7):hash;if(hash.startsWith('f_'))$('#mode').value='records'}update();
'''

def embedded(obj):return json.dumps(obj,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
def page(title,body,data=None,script=''):
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+STYLE+'</style>'+body+(('<script type="application/json" id="data">'+embedded(data)+'</script>') if data is not None else '')+('<script>'+script+'</script>' if script else '')+'</html>'
def main():
    DEST.mkdir(exist_ok=True)
    records=load_records();tokens=load_analysis_tokens(records);anns=load_annotations();fams={r['family_id']:r for r in tsv('families.tsv')};anc=load_ancestors()
    groups=defaultdict(list)
    for r in tokens:
        r['display_outcome']=outcome(r)
        groups[r['research_family_id']].append(r)
    dossiers=[]
    for fid,f in fams.items():
        rr=groups[fid];ids=sorted({r['research_ancestor_id'] for r in rr if r['research_ancestor_id']})
        panel={l:[] for l in LANGS}
        for r in rr:
            v=dict(form=r['reading_form'],meaning=r['research_gloss'],outcome=r['display_outcome'],source=r['source_keys'],lect=lect(r),exclusion=r['strict_exclusion'])
            if v not in panel[r['language_id']]:panel[r['language_id']].append(v)
        dossiers.append({**f,**anns[fid], 'research_token_count':len(rr),'record_ids':sorted({r['id'] for r in rr}),
            'analysis_token_ids':[r['analysis_token_id'] for r in rr], 'ancestors':[anc[i] for i in ids if i in anc], 'language_panel':panel})
    # Full machine-readable data: tokens retain every original field and all decisions.
    for name,rows in [('family-dossiers.jsonl',dossiers),('complete-records.jsonl',records),('analysis-tokens.jsonl',tokens)]:
        (DEST/name).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
    coverage=[]
    for l in LANGS:
        rr=[r for r in records if r['language_id']==l]
        coverage.append('<tr><td>'+NAMES[l]+'</td><td>'+str(len(rr))+'</td><td>'+str(sum(bool(r['family_id']) for r in rr))+'</td><td>'+str(sum(bool(r['research_family_id']) for r in rr))+'</td><td>'+str(sum(r['individual_review'] not in ['family-context-first-pass','unlinked-inventory'] for r in rr))+'</td></tr>')
    body='''<header><div class="eyebrow">Shinaic accent · Complete research appendices</div><h1>Every family, every record, every decision</h1><p>Search the 1,686 family dossiers or all 25,593 analysis tokens derived from 25,505 raw records. Source readings, uncertain ancestry and exceptions remain visible. All seven living Shinaic languages are included.</p><p class="notice">Every linked family has a first-pass etymological analysis. Record-level and printed-source verification are explicitly uneven: “family-context-first-pass” is not an individual primary-source check. Unmarked forms are not classified as toneless.</p><div class="downloads"><a href="../REPORT.html">Narrative report</a><a href="tables.html">Quantitative tables</a><a href="sources.html">Sources and notation</a><a href="proposals.html">Etymological proposals</a><a href="data-dictionary.md">Data dictionary</a><a href="../annotated-records.tsv">Complete raw-record TSV</a><a href="../analysis-tokens.tsv">Complete token TSV</a><a href="family-dossiers.jsonl">Dossiers JSONL</a></div></header><main><details><summary>Coverage and review levels</summary><div class="scroll"><table><thead><tr><th>Language</th><th>Raw records</th><th>Raw linked</th><th>Research linked</th><th>Explicit record/group assessment</th></tr></thead><tbody>'''+''.join(coverage)+'''</tbody></table></div><p>Explicit assessment includes manually reviewed source/gloss groups, identity links, morphological comparisons and primary readings; these are different evidence levels, recorded on each item. Old Shina is registered but has no records. Supplementary new-family proposals are listed separately and do not inflate the frozen family count.</p></details><div class="toolbar"><label>View<select id="mode"><option value="families">Family dossiers</option><option value="records">All records / analysis tokens</option></select></label><label>Search<input id="search" type="search" placeholder="Etymon, form, meaning, family ID, source…" aria-label="Search appendices"></label><label>Language<select id="language"><option value="">All languages</option>'''+''.join('<option value="'+l+'">'+NAMES[l]+'</option>' for l in LANGS)+'''</select></label><label>Record review filter<select id="review"><option value="">All records</option><option value="unlinked">Unlinked ancestry</option><option value="excluded">Excluded from strict predictions</option><option value="explicit">Explicit assessment</option></select></label></div><p id="count" class="count" aria-live="polite">Loading complete appendices…</p><div id="results"></div><div class="pager"><button id="prev">Previous</button><button id="next">Next</button><span class="muted">30 results per page · open a dossier for all its forms</span></div></main><footer>Frozen database extract: 9 September 2026. All scholarly changes are research-only; the Jambu database is unchanged. E/L = early/late mora in the specified source system; H1/H2 = Kalkoti High association; stress is a separate outcome. See the source register before comparing symbols.</footer>'''
    (DEST/'index.html').write_text(page('Shinaic accent — complete appendices',body,dict(records=tokens,families=dossiers,languages=LANGS,names=NAMES),SCRIPT))
    print('appendices',len(dossiers),'families',len(records),'records',len(tokens),'tokens')
if __name__=='__main__':main()
